<script setup lang="ts">
import PaymentSummary from '../components/PaymentSummary.vue'
import { useCardMotion } from '../composables/useCardMotion'
import Select from 'primevue/select'
import Button from 'primevue/button'
import MaintenanceAiDialog from '../components/MaintenanceAiDialog.vue'
import { WandSparkles } from 'lucide-vue-next'
import type { MaintenanceAiDraft } from '../services/types'

import { ref,watch,computed } from 'vue'
import { useRoute } from 'vue-router'
import { Pencil,Trash2,Paperclip,ChevronLeft,ChevronRight } from 'lucide-vue-next'
import { useGarage } from '../stores/garage'
import { api } from '../services/api'
import type { Page,RecordEntry } from '../services/types'
import { categories,serviceTypes,money,date,number } from '../services/types'
import EmptyState from '../components/EmptyState.vue'
import RecordDialog from '../components/RecordDialog.vue'
import FormDatePicker from '../components/FormDatePicker.vue'
const g=useGarage(),route=useRoute(),rows=ref<RecordEntry[]>([]),total=ref(0),page=ref(1),from=ref(''),to=ref(''),category=ref(''),component=ref(typeof route.query.component==='string'?route.query.component:''),subcomponent=ref(typeof route.query.subcomponent==='string'?route.query.subcomponent:''),busy=ref(false),error=ref(''),open=ref(false),edit=ref<RecordEntry|null>(null)
const aiOpen=ref(false),aiDraft=ref<MaintenanceAiDraft|null>(null)
function interpreted(draft:MaintenanceAiDraft){edit.value=null;aiDraft.value=draft;open.value=true}
function manual(){edit.value=null;aiDraft.value=null;open.value=true}
function editAiMessage(){open.value=false;aiOpen.value=true}
watch(open,value=>{if(!value)aiDraft.value=null})
const subOptions=computed(()=>component.value?g.components.find(c=>c.id===component.value)?.subcomponents??[]:g.components.flatMap(c=>c.subcomponents.map(s=>({...s,name:c.name+' · '+s.name}))))
watch(component,()=>{if(!subOptions.value.some(s=>s.id===subcomponent.value))subcomponent.value=''})
let version=0
async function load(){if(!g.selectedId)return;const v=++version;busy.value=true;error.value='';try{const q=new URLSearchParams({page:String(page.value),pageSize:'10'});if(from.value)q.set('from',from.value);if(to.value)q.set('to',to.value);if(category.value)q.set('category',category.value);if(component.value)q.set('component',component.value);if(subcomponent.value)q.set('subcomponent',subcomponent.value);const r=await api<Page<RecordEntry>>(`/vehicles/${g.selectedId}/records?${q}`);if(v===version){rows.value=r.items;total.value=r.total}}catch(e){if(v===version)error.value=(e as Error).message}finally{if(v===version)busy.value=false}}
watch([page,()=>g.selectedId,()=>g.dataRevision],load,{immediate:true})
function filter(){if(page.value===1)load();else page.value=1}
async function remove(r:RecordEntry){if(!confirm('Excluir este serviço, suas peças e anexos?'))return;try{await api(`/vehicles/${g.selectedId}/records/${r.id}`,{method:'DELETE'});await load();await g.refresh()}catch(e){error.value=(e as Error).message}}
const { cardInitial, cardEnter } = useCardMotion()
</script>
<template><template v-if="g.selected"><div class="history-ai-actions"><Button class="button" @click="aiOpen=true"><WandSparkles :size="17"/>Registrar com IA</Button></div><form class="filter-bar panel" @submit.prevent="filter"><label for="history-from">De<FormDatePicker input-id="history-from" v-model="from" /></label><label for="history-to">Até<FormDatePicker input-id="history-to" v-model="to" /></label><label for="history-category">Categoria<Select aria-label="Categoria" input-id="history-category" v-model="category" :options="Object.entries(categories).map(([value,label])=>({value,label}))" option-label="label" option-value="value" placeholder="Todas as categorias" show-clear /></label><label for="history-component">Componente<Select aria-label="Componente" input-id="history-component" v-model="component" :options="g.components" option-label="name" option-value="id" placeholder="Todos os componentes" show-clear /></label><label for="history-subcomponent">Subcomponente<Select aria-label="Subcomponente" input-id="history-subcomponent" v-model="subcomponent" :options="subOptions" option-label="name" option-value="id" placeholder="Todos os subcomponentes" show-clear /></label><Button type="submit" class="button" :disabled="busy">Filtrar</Button></form><div class="section-header"><p class="muted">{{total}} serviços encontrados</p><span v-if="busy" role="status">Carregando…</span></div><p v-if="error" class="error-banner" role="alert">{{error}}</p><div class="timeline"><article v-for="r in rows" :key="r.id" class="timeline-record"><div class="timeline-date"><strong>{{date(r.date)}}</strong><span>{{r.mileage==null?'Km não informada':number(r.mileage)+' km'}}</span></div><div v-motion :initial="cardInitial" :enter="cardEnter(30)" class="timeline-content panel"><div class="section-header"><span class="service-type">{{serviceTypes[r.serviceType]}}</span><div class="record-actions"><Button class="icon-button" :aria-label="'Editar serviço '+r.description" @click="edit=r;open=true"><Pencil :size="16"/></Button><Button class="icon-button danger" :aria-label="'Excluir serviço '+r.description" @click="remove(r)"><Trash2 :size="16"/></Button></div></div><h2>{{r.description}}</h2><p class="muted">{{categories[r.category]}}{{r.workshop?' · '+r.workshop:''}}</p><p v-if="r.mechanicName" class="record-mechanic">Mecânico: {{r.mechanicName}}</p><div class="record-components"><span v-for="c in r.components" :key="c.id">{{c.name}}{{r.primaryComponentId===c.id?' · principal':''}}</span></div><p v-if="r.subcomponents.length" class="record-subcomponents">{{r.subcomponents.map(s=>s.name).join(' · ')}}</p><div v-if="r.items.length" class="record-parts"><div v-for="i in r.items" :key="i.id" class="data-row"><span>{{i.quantity}} × {{i.name}}</span><span>{{i.total==null?'Incluído no total':money(i.total)}}</span></div></div><p v-if="r.notes" class="record-notes">{{r.notes}}</p><div v-if="r.attachments.length" class="attachments"><a v-for="a in r.attachments" :key="a.id" :href="a.url" target="_blank" rel="noopener"><Paperclip :size="15"/>{{a.fileName}}</a></div><PaymentSummary :record="r" /><div class="record-totals"><span v-if="r.packageTotal!=null">Valor total fechado · sem detalhamento</span><template v-else><span>Peças <b>{{money(r.partsCost??0)}}</b></span><span>Mão de obra <b>{{money(r.laborCost??0)}}</b></span></template><span v-if="r.interestCost>0">Juros <b>{{money(r.interestCost)}}</b></span><span v-if="r.pendingPaymentCount">Total conhecido · juros pendentes</span><strong>{{money(r.totalCost)}}</strong></div></div></article></div><EmptyState v-if="!rows.length&&!busy" title="Nenhum serviço neste período" description="Ajuste os filtros ou registre o primeiro cuidado do veículo."/><div v-if="total>10" class="pagination"><Button class="button" :disabled="page===1" aria-label="Página anterior" @click="page--"><ChevronLeft :size="16"/></Button><span>Página {{page}} de {{Math.ceil(total/10)}}</span><Button class="button" :disabled="page*10>=total" aria-label="Próxima página" @click="page++"><ChevronRight :size="16"/></Button></div></template><EmptyState v-else title="Selecione um veículo" description="O histórico aparecerá aqui após o cadastro de um veículo."/><MaintenanceAiDialog v-model:visible="aiOpen" @interpreted="interpreted" @manual="manual"/><RecordDialog v-model:visible="open" :record="edit" :ai-draft="aiDraft" @edit-ai-message="editAiMessage" @saved="load();g.refresh()"/></template>
